static const struct {
  NI cap; NIM_CHAR data[13958+1];
} TM__6omQKptA48tIwjWAyUFyvQ_209 = { 13958 | NIM_STRLIT_FLAG, "\' Heartleaf reference villager.\012\'\012\' You are one villager in a nine-house village. Every decision runs from the\012\' top of this file with a fresh instruction budget, once per game minute.\012\' Globals and arrays survive between decisions; registers do not.\012\'\012\' THE WEEK. Days run 9:00 to 21:00. Every morning each of the 27 gardens\012\' grows one vegetable. At exactly 18:00 every house holds its dinner tally:\012\' if the owner is inside with at least one visitor, the owner banks\012\' (items carried) x (visitor count), then the pantry feeds everyone present\012\' for three bite rounds - a vegetable you have never tasted is worth 3,\012\' a repeat 1. Hosting empties your bag. Anyone alone, or outside, scores\012\' nothing that night. Be inside your own house by 21:00 or lose 3 points.\012\' Highest total after the last day wins.\012\'\012\' READ-ONLY VALUES\012\'   selfSlot worldTick day dayCount minuteOfDay dinnerDone\012\'   myX myY inHouse carried hosting acceptedHost orderKind orderTarget\012\'   score villagerTotal gardenTotal decisionPeriod\012\' minuteOfDay counts minutes since midnight: 540 is 9:00, 1080 is 18:00.\012\' inHouse is the house you are inside, or -1 outdoors.\012\' orderKind: 0 idle, 1 walking, 2 gathering, 3 heading home, 4 talking.\012\'\012\' QUERIES\012\'   invOf(v) eatenOf(v)                    your bag and your palate\012\'   gardenX(i) gardenY(i) gardenVeggie(i)  gardenVeggie is -1 when bare\012\'   nearestStockedGarden() nearestWinnableGarden()  garden id or -1\012\'   gardenOutpaced(i)                      another gatherer leads by 3+ tiles\012\'   villagerX(s) villagerY(s) villagerInHouse(s) villagerHosting(s)\012\'   villagerCarried(s) villagerScore(s) inviteFrom(s)\012\'   talkingTo(s) socialAvailable(s) socialGroupSize(s) inMyConversation(s) sameConversation(a, b)\012\'   doorX(h) doorY(h) occupants(h)\012\'   distTo(x, y) distance(x1, y1, x2, y2) tilePassable(x, y)\012\'\012\' COMMANDS, all return 1 when accepted and 0 when refused.\012\'   walkTo(x, y)   gather(gardenId)  invite(s)   accept(s)   decline(s)\012\'   enterHouse(h)  exitHouse()       cancel()    orderFailed()\012\'   talk(s)        offer or join a nearby conversation, up to four gnomes\012\' invite needs both of you outdoors within 3 tiles, and declares you a host.\012\' Entering a house hides you from the map until you exitHouse().\012\'\012\' THE PLAYBOOK. Gather all day; three villagers are due to host each night\012\' by rotation; guests walk to the nearest due host; never be alone at six.\012\012dim invitedMark(8)\012dim avoidUntil(8)\012\012\' A small counter generator of our own, seeded by slot, so each villager\012\' wanders and pauses on their own rhythm. call rnd(n) leaves the next\012\' draw, 0..n-1, in rndOut.\012if rngState = 0 then\012  rngState = selfSlot * 7919 + 17\012end if\012sub rnd(n)\012  rngState = (rngState * 75 + 74) mod 65537\012  rndOut = rngState mod n\012end sub\012\012\' Count outdoor company without treating hidden house occupants as a crowd.\012sub company(x, y)\012  neighbors = 0\012  other = 0\012  while other < villagerTotal\012    if other <> selfSlot and villagerInHouse(other) < 0 then\012      if distance(x, y, villagerX(other), villagerY(other)) <= 4 then\012        neighbors = neighbors + 1\012      end if\012    end if\012    other = other + 1\012  wend\012end sub\012\012sub canMeet(candidate)\012  meetAllowed = 1\012  member = 0\012  while member < villagerTotal\012    if member <> selfSlot and worldTick < avoidUntil(member) then\012      if sameConversation(candidate, member) = 1 then\012        meetAllowed = 0\012      end if\012    end if\012    member = member + 1\012  wend\012end sub\012\012sub beginChat(peer)\012  call canMeet(peer)\012  r = 0\012  if meetAllowed = 1 then\012    r = talk(peer)\012  end if\012  if r = 1 then\012    call rnd(289)\012    chatUntil = worldTick + 288 + rndOut\012    social = -1\012    wandering = 0\012    engaged = 1\012    aloneSince = worldTick\012  end if\012end sub\012\012sub leaveGroup()\012  tries = 0\012  while tries < 12\012    call rnd(21)\012    x = leaveX + rndOut - 10\012    call rnd(21)\012    y = leaveY + rndOut - 10\012    d = distance(x, y, leaveX, leaveY)\012    call company(x, y)\012    if d >= 8 and d <= 10 and tilePassable(x, y) = 1 and neighbors <= 1 then\012      r = walkTo(x, y)\012      if r = 1 then\012        tries = 12\012      end if\012    end if\012    tries = tries + 1\012  wend\012end sub\012\012sub leisure()\012  f = orderFailed()\012  engaged = 0\012  g = nearestWinnableGarden()\012  if orderKind = 2 then\012    if worldTick >= harvestCheck then\012      harvestCheck = worldTick + 48\012      if gardenOutpaced(orderTarget) = 1 then\012        r = cancel()\012      end if\012    end if\012  else\012    if g >= 0 then\012      r = gather(g)\012      wandering = 0\012      leisureReady = 0\012      social = -1\012      leaving = 0\012    else\012      if orderKind = 4 then\012        peer = 0\012        while peer < villagerTotal\012          if inMyConversation(peer) = 1 then\012            avoidUntil(peer) = worldTick + 1080\012          end if\012          peer = peer + 1\012        wend\012        if worldTick >= chatUntil then\012          call rnd(721)\012          reunionAfter = worldTick + 1080 + rndOut\012          peer = 0\012          while peer < villagerTotal\012            if inMyConversation(peer) = 1 then\012              avoidUntil(peer) = reunionAfter\012            end if\012            peer = peer + 1\012          wend\012          r = cancel()\012          socialAfter = worldTick + 240\012          aloneSince = worldTick\012          leisureReady = 0\012          social = -1\012          leaving = 1\012          leaveX = myX\012          leaveY = myY\012          call leaveGroup()\012        end if\012      else\012        if leaving = 1 then\012          if distTo(leaveX, leaveY) >= 7 then\012            leaving = 0\012            leisureReady = 0\012          else\012            if orderKind = 0 then\012              call leaveGroup()\012            end if\012          end if\012          engaged = 1\012        end if\012        \' Acknowledge a neighbor who has stopped to talk to us.\012        if engaged = 0 and worldTick >= socialAfter then\012          peer = 0\012          while peer < villagerTotal and engaged = 0\012            if peer <> selfSlot and talkingTo(peer) = selfSlot and worldTick >= avoidUntil(peer) then\012              if distTo(villagerX(peer), villagerY(peer)) <= 4 then\012                call beginChat(peer)\012              end if\012            end if\012            peer = peer + 1\012          wend\012        end if\012        if engaged = 0 and social >= 0 then\012          if socialAvailable(social) = 0 or socialGroupSize(social) >= 4 then\012            r = cancel()\012            social = -1\012            wandering = 0\012          else\012            if distTo(villagerX(social), villagerY(social)) <= 3 then\012              call beginChat(social)\012            else\012              if distance(ax, ay, villagerX(social), villagerY(social)) > 3 then\012                r = cancel()\012                social = -1\012                wandering = 0\012              end if\012            end if\012          end if\012        end if\012        if engaged = 0 and orderKind = 0 then\012          if leisureReady = 0 then\012            leisureReady = 1\012            leisureX = myX\012            leisureY = myY\012            previousStop = 0\012            call rnd(121)\012            pauseUntil = worldTick + 120 + rndOut\012          end if\012          if wandering = 1 then\012            wandering = 0\012            call rnd(121)\012            pauseUntil = worldTick + 120 + rndOut\012          end if\012\012          \' Seek a neighbor or a small gathering, favoring nearby company.\012          social = -1\012          if worldTick >= socialAfter then\012            best = 100000\012            peer = 0\012            while peer < villagerTotal\012              if peer <> selfSlot and worldTick >= avoidUntil(peer) and socialAvailable(peer) = 1 then\012                d = distTo(villagerX(peer), villagerY(peer))\012                reach = 14\012                if worldTick - aloneSince >= 480 then\012                  reach = 64\012                end if\012                call canMeet(peer)\012                call company(villagerX(peer), villagerY(peer))\012                if neighbors >= 3 then\012                  meetAllowed = 0\012                end if\012                if meetAllowed = 1 and d <= reach and socialGroupSize(peer) < 4 then\012                  if d < best then\012                    best = d\012                    social = peer\012                  end if\012                end if\012              end if\012              peer = peer + 1\012            wend\012          end if\012          if social >= 0 then\012            if best <= 3 then\012              call beginChat(social)\012            end if\012          end if\012          if engaged = 0 then\012            call company(myX, myY)\012            if neighbors >= 4 then\012              pauseUntil = worldTick\012            end if\012            if social >= 0 or worldTick >= pauseUntil then\012              ax = myX\012              ay = myY\012              if social >= 0 then\012                ax = villagerX(social)\012                ay = villagerY(social)\012              end if\012              tries = 0\012              while tries < 6\012                call rnd(7)\012                dx = rndOut - 3\012                call rnd(7)\012                dy = rndOut - 3\012                x = ax + dx\012                y = ay + dy\012                nearby = distTo(x, y)\012                backtracking = previousStop = 1 and distance(x, y, previousX, previousY) <= 2\012                limit = 6\012                if social >= 0 then\012                  limit = 67\012                end if\012                if nearby >= 2 and nearby <= limit and backtracking = 0 then\012                  if tilePassable(x, y) = 1 and (social >= 0 or distance(x, y, leisureX, leisureY) <= 8) then\012                    call company(x, y)\012                    if neighbors <= 2 then\012                      r = walkTo(x, y)\012                      if r = 1 then\012                        wandering = 1\012                        previousStop = 1\012                        previousX = myX\012                        previousY = myY\012                        tries = 6\012                      end if\012                    end if\012                  end if\012                end if\012                tries = tries + 1\012              wend\012              if wandering = 0 then\012                pauseUntil = worldTick + 72\012              end if\012            end if\012          end if\012        end if\012      end if\012    end if\012  end if\012end sub\012\012\' New-day reset.\012if dayMark <> day then\012  dayMark = day\012  returningHome = 0\012  harvestCheck = 0\012  houseCheck = 0\012  houseTarget = -1\012  wandering = 0\012  leisureReady = 0\012  social = -1\012  pauseUntil = 0\012  socialAfter = worldTick + selfSlot * 12\012  aloneSince = worldTick\012  leaving = 0\012  chatUntil = 0\012  s = 0\012  while s < villagerTotal\012    invitedMark(s) = 0\012    avoidUntil(s) = 0\012    s = s + 1\012  wend\012end if\012\012\' Retry an approach if it has made no tile progress for two seconds.\012if worldTick >= houseCheck then\012  houseCheck = worldTick + 48\012  if orderKind = 1 then\012    if moveChecking = 1 and distTo(moveX, moveY) <= 1 then\012      r = cancel()\012      social = -1\012      wandering = 0\012    end if\012    moveChecking = 1\012    moveX = myX\012    moveY = myY\012  else\012    moveChecking = 0\012  end if\012  if orderKind = 3 then\012    if houseTarget = orderTarget and distTo(houseX, houseY) <= 1 then\012      r = enterHouse(orderTarget)\012    end if\012    houseTarget = orderTarget\012    houseX = myX\012    houseY = myY\012  else\012    houseTarget = -1\012  end if\012end if\012\012\' Am I due to host tonight\? Rotation puts three hosts on every night.\012hostTonight = 0\012if (day + selfSlot) mod 3 = 0 then\012  hostTonight = 1\012end if\012\012if dinnerDone = 1 then\012  \' Allow for detours through gates and around planted gardens on the way home.\012  homeMinutes = distTo(doorX(selfSlot), doorY(selfSlot)) * 4 + 60\012  if 1260 - minuteOfDay <= homeMinutes or minuteOfDay >= 1200 then\012    returningHome = 1\012  end if\012  if returningHome = 1 then\012    if inHouse >= 0 then\012      if inHouse <> selfSlot then\012        r = exitHouse()\012        leisureReady = 0\012      end if\012    else\012      if orderKind <> 3 or orderTarget <> selfSlot then\012        r = enterHouse(selfSlot)\012      end if\012    end if\012  else\012    if inHouse >= 0 then\012      r = exitHouse()\012      leisureReady = 0\012    else\012      call leisure()\012    end if\012  end if\012else\012  \' Accept the first standing invitation.\012  if acceptedHost < 0 then\012    s = 0\012    while s < villagerTotal\012      if inviteFrom(s) = 1 then\012        r = accept(s)\012        s = villagerTotal\012      end if\012      s = s + 1\012    wend\012  end if\012\012  \' Where is dinner tonight\? Hosts stay home. Guests follow an accepted\012  \' invitation, or walk to the nearest villager whose rotation night it is.\012  target = selfSlot\012  if hostTonight = 0 then\012    if acceptedHost >= 0 then\012      target = acceptedHost\012    else\012      bestDist = 100000\012      s = 0\012      while s < villagerTotal\012        if s <> selfSlot then\012          if (day + s) mod 3 = 0 then\012            d = distTo(doorX(s), doorY(s))\012            if d < bestDist then\012              bestDist = d\012              target = s\012            end if\012          end if\012        end if\012        s = s + 1\012      wend\012    end if\012  end if\012\012  \' Budget extra time for fences and shrubs, plus a half-hour for door crowds.\012  \' Five o\'clock is the hard deadline for starting the walk to dinner.\012  minutesLeft = 1080 - minuteOfDay\012  walkMinutes = distTo(doorX(target), doorY(target)) * 4\012  going = 0\012  if minutesLeft <= walkMinutes + 30 then\012    going = 1\012  end if\012  if minuteOfDay >= 1020 then\012    going = 1\012  end if\012\012  if going = 1 then\012    if inHouse < 0 then\012      alreadyHeading = 0\012      if orderKind = 3 and orderTarget = target then\012        alreadyHeading = 1\012      end if\012      if alreadyHeading = 0 then\012        r = enterHouse(target)\012      end if\012    end if\012  else\012    \' Daytime. Hosts wave invitations at anyone passing close by.\012    if hostTonight = 1 then\012      s = 0\012      while s < villagerTotal\012        if s <> selfSlot then\012          if invitedMark(s) = 0 then\012            if villagerInHouse(s) < 0 then\012              d = distTo(villagerX(s), villagerY(s))\012              if d <= 3 then\012                r = invite(s)\012                if r = 1 then\012                  invitedMark(s) = 1\012                end if\012              end if\012            end if\012          end if\012        end if\012        s = s + 1\012      wend\012    end if\012\012    call leisure()\012  end if\012end if\012" };
